using System;
using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        int i = 0;

        if (Vector.IsHardwareAccelerated && data.Length >= Vector<int>.Count)
        {
            var thresholdVec = new Vector<int>(threshold);
            var oneVec = Vector<int>.One;

            // Process two vectors per iteration to improve ILP
            int twoVecs = Vector<int>.Count * 2;
            ref int baseRef = ref MemoryMarshal.GetReference(data);

            int limit2 = data.Length - twoVecs + 1;
            for (; i < limit2; i += twoVecs)
            {
                ref int p0 = ref Unsafe.Add(ref baseRef, i);
                ref int p1 = ref Unsafe.Add(ref baseRef, i + Vector<int>.Count);

                var v0 = Unsafe.ReadUnaligned<Vector<int>>(ref Unsafe.As<int, byte>(ref p0));
                var v1 = Unsafe.ReadUnaligned<Vector<int>>(ref Unsafe.As<int, byte>(ref p1));

                // GreaterThan returns -1 (all bits set) for true, which IsNegative uses as mask
                var mask0 = Vector.GreaterThan(v0, thresholdVec);
                var mask1 = Vector.GreaterThan(v1, thresholdVec);

                // Subtract mask (-1 becomes +1, 0 stays 0)
                v0 -= mask0;
                v1 -= mask1;

                Unsafe.WriteUnaligned(ref Unsafe.As<int, byte>(ref p0), v0);
                Unsafe.WriteUnaligned(ref Unsafe.As<int, byte>(ref p1), v1);
            }

            int limit1 = data.Length - Vector<int>.Count + 1;
            for (; i < limit1; i += Vector<int>.Count)
            {
                ref int p = ref Unsafe.Add(ref baseRef, i);
                var v = Unsafe.ReadUnaligned<Vector<int>>(ref Unsafe.As<int, byte>(ref p));
                var mask = Vector.GreaterThan(v, thresholdVec);
                v -= mask;
                Unsafe.WriteUnaligned(ref Unsafe.As<int, byte>(ref p), v);
            }
        }

        // Scalar tail
        for (; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }
}

